    #region Private Methods
    /// <summary>The pre-migration read, factored out so the recovery path can repeat it verbatim.</summary>
    private static bool SeedHistoryAndCheckPending(IDbContextFactory<LoggingContext> contextFactory, string databasePath)
    {
        SeedMigrationHistoryIfNeeded(databasePath);
        SqliteConnection.ClearAllPools();
        return HasPendingMigrations(contextFactory);
    }

    /// <summary>The migration itself, factored out for the same reason.</summary>
    private static void RunMigrations(IDbContextFactory<LoggingContext> contextFactory)
    {
        using var context = contextFactory.CreateDbContext();
        context.Database.Migrate();
    }

    /// <summary>
    /// Searches an exception and its inner chain for SQLite saying the database FILE'S CONTENT is
    /// unusable, which is the only kind of failure a quarantine is a valid answer to.
    /// </summary>
    /// <remarks>
    /// Asking the operation that actually failed, rather than probing up front, is deliberate. A
    /// cheap pre-flight query (<c>SELECT COUNT(*) FROM sqlite_master</c>) validates the header and
    /// the schema catalog and nothing else — measured: a database whose pages past page 1 are
    /// overwritten passes it and then throws <c>SQLITE_CORRUPT</c> on the very next table read, so
    /// a probe-first design would have left that file in place and crashed startup anyway. The
    /// thorough pre-flight, <c>PRAGMA integrity_check</c>, walks the whole file, and this runs on
    /// every launch of an app whose database routinely holds millions of samples. Catching the real
    /// failure costs nothing on a healthy launch and covers exactly the reads that happen.
    /// <para>
    /// The chain walk matters because EF Core wraps provider exceptions; the corruption is often the
    /// inner one.
    /// </para>
    /// </remarks>
    private static SqliteException? FindContentCorruption(Exception? exception)
    {
        for (var current = exception; current is not null; current = current.InnerException)
        {
            if (current is SqliteException sqlite && sqlite.SqliteErrorCode is SQLITE_CORRUPT or SQLITE_NOTADB)
            {
                return sqlite;
            }
        }

        return null;
    }

    /// <summary>
    /// Moves a proven-unreadable database file aside so the caller can create a fresh one, and
    /// records where it went.
    /// </summary>
    /// <remarks>
    /// The damaged file is RENAMED, never deleted: it is the user's logged data, and a corrupt
    /// SQLite file is frequently still partly recoverable with <c>sqlite3 .recover</c>.
    /// </remarks>
    /// <param name="databasePath">Full path to the SQLite database file.</param>
    /// <param name="fault">The exception proving the file is unreadable, for the log.</param>
    /// <returns>The path the file was moved to, or <c>null</c> if nothing was moved.</returns>
    private static string? QuarantineDatabase(string databasePath, Exception fault)
    {
        if (!File.Exists(databasePath))
        {
            // Corruption reported for a path with no file at it: nothing to move, and creating a
            // quarantine name for it would say something untrue.
            return null;
        }

        // Drop any pooled handle on the file first, or the move fails on Windows.
        SqliteConnection.ClearAllPools();

        // Millisecond precision, and every move below uses overwrite:false, so an earlier quarantine
        // can never be clobbered — the whole point is that nothing the user might still recover gets
        // destroyed. A same-millisecond collision fails the move instead, which the loop treats like
        // any other failure and undoes.
        var quarantinePath = $"{databasePath}.corrupt-{DateTime.UtcNow:yyyyMMdd-HHmmssfff}";

        // Within one process the move below is exact. Against a SECOND DAQiFi instance it is not,
        // and cannot be here: the app has no cross-process database ownership guard at all (no named
        // mutex, no lock file — two instances already share this file today, entirely independently
        // of this recovery), and ClearAllPools only releases this process's handles. What bounds it
        // is that a quarantine only ever runs on a file SQLite has just refused to read, so a second
        // instance reaches the same failure rather than writing a journal next to it.
        if (MoveDatabaseSet(databasePath, quarantinePath) is null)
        {
            return null;
        }

        QuarantinedDatabasePath = quarantinePath;
        AppLogger.Instance.Error(fault,
            $"Database at '{databasePath}' could not be read and was moved to '{quarantinePath}'. " +
            "A new, empty database will be created; previously logged sessions are not in it.");

        return quarantinePath;
    }

    /// <summary>
    /// Moves the database and every journal sidecar from <paramref name="databasePath"/> to
    /// <paramref name="destinationPathPrefix"/> plus the same suffix — all of it or none of it.
    /// </summary>
    /// <remarks>
    /// Three reasons this has to be atomic rather than best-effort:
    /// <list type="bullet">
    ///   <item>a journal can hold the only committed copy of the user's last samples, so it must
    ///   stay with the database it belongs to;</item>
    ///   <item>one left beside a REPLACEMENT database is not inert — SQLite rolls back a hot
    ///   <c>-journal</c>, and replays a <c>-wal</c> whose header still checksums, either way writing
    ///   the old file's pages into the new one;</item>
    ///   <item>every caller picks a fresh timestamped destination, so a half-moved set could never
    ///   be reunited by a later attempt.</item>
    /// </list>
    /// Nothing is ever deleted here: a file that cannot be moved is put back, not removed. Every
    /// move uses <c>overwrite: false</c>, so an existing destination fails the move rather than
    /// clobbering something the user might still want.
    /// <para>
    /// Shared by the two callers that need the database out of the way — the corruption quarantine
    /// and the "Delete All Sessions" purge — so there is one implementation of "relocate the whole
    /// artefact" rather than two that drift on which sidecars exist and what happens half way.
    /// </para>
    /// </remarks>
    /// <returns>
    /// The moves that were made (empty when there was no database to move), or <c>null</c> when the
    /// set could not be moved and every move already made has been undone.
    /// </returns>
    private static List<(string From, string To)>? MoveDatabaseSet(string databasePath, string destinationPathPrefix)
    {
        var moved = new List<(string From, string To)>();

        foreach (var suffix in DatabaseFileSuffixes)
        {
            var source = databasePath + suffix;
            if (!File.Exists(source))
            {
                continue;
            }

            var destination = destinationPathPrefix + suffix;
            try
            {
                File.Move(source, destination, overwrite: false);
                moved.Add((source, destination));
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex,
                    $"Could not move '{source}' to '{destination}', so the relocation of '{databasePath}' is being undone. " +
                    "A half-moved set of database files is never left behind.");
                UndoMoves(moved);
                return null;
            }
        }

        return moved;
    }

    /// <summary>
    /// Undoes a purge whose replacement could not be built: clears away whatever the failed
    /// migration left at the live path and puts the user's database back.
    /// </summary>
    /// <remarks>
    /// The half-built replacement has to go first, because <see cref="UndoMoves"/> moves with
    /// <c>overwrite: false</c> and would otherwise refuse. It is safe to delete precisely because it
    /// is seconds old and holds nothing: it was created by the migration that just failed. If even
    /// that cannot be deleted, the old data stays under its relocated name rather than being put
    /// back — which the returned exception says out loud, with the path, so it is never lost
    /// silently.
    /// </remarks>
    /// <returns>The exception to throw, describing what the user's data is now doing.</returns>
    private static DatabaseReplacementException RestoreAfterFailedReplacement(
        string databasePath,
        string relocatedPath,
        List<(string From, string To)> moved,
        Exception fault)
    {
        // The failed migration may still hold a pooled handle on the file it created.
        SqliteConnection.ClearAllPools();

        foreach (var suffix in DatabaseFileSuffixes)
        {
            var leftover = databasePath + suffix;
            if (!File.Exists(leftover))
            {
                continue;
            }

            try
            {
                File.Delete(leftover);
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex,
                    $"Could not remove '{leftover}', left by a failed rebuild, so the original database "
                    + $"cannot be put back and stays at '{relocatedPath}'.");

                return new DatabaseReplacementException(
                    "The logged data could not be deleted, and the original database could not be put "
                    + $"back either. It has been preserved at '{relocatedPath}' — nothing was destroyed. "
                    + "Close any other copy of DAQiFi, restart, and contact support if the Logged Data "
                    + "pane is still empty.",
                    relocatedPath,
                    fault);
            }
        }

        UndoMoves(moved);

        return new DatabaseReplacementException(
            "The logged data could not be deleted because an empty database could not be created in "
            + "its place. Nothing was deleted — your logging sessions are exactly as they were. Check "
            + "that there is free disk space and that the DAQiFi data folder is writable, then try again.",
            relocatedDatabasePath: null,
            fault);
    }

    /// <summary>
    /// Deletes the set a successful purge moved aside. Best-effort: the user's request has already
    /// been honoured (the live database is empty), so a file that will not go is a leftover to log
    /// rather than a reason to fail the operation and re-show sessions that are gone.
    /// </summary>
    private static void DeleteRelocatedSet(List<(string From, string To)> moved)
    {
        foreach (var (_, to) in moved)
        {
            try
            {
                File.Delete(to);
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex,
                    $"Deleted all logging sessions, but the old database file '{to}' could not be removed. "
                    + "Delete it by hand; it holds the sessions that were just deleted.");
            }
        }
    }

    /// <summary>
    /// Puts every file an abandoned relocation had already moved back where it came from, newest
    /// move first. Best-effort by necessity — there is nothing left to try if this fails — so each
    /// failure is logged with both paths, which is what a support log needs to say.
    /// </summary>
    private static void UndoMoves(List<(string From, string To)> moved)
    {
        for (var i = moved.Count - 1; i >= 0; i--)
        {
            var (from, to) = moved[i];
            try
            {
                File.Move(to, from, overwrite: false);
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex,
                    $"Could not put '{to}' back as '{from}' while undoing an abandoned relocation. Move it back by hand.");
            }
        }
    }

    /// <summary>
    /// Checks whether there are any pending migrations to apply.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.HasPendingMigrations
    private static bool HasPendingMigrations(IDbContextFactory<LoggingContext> contextFactory)
    {
        using var context = contextFactory.CreateDbContext();
        var pending = context.Database.GetPendingMigrations();
        return pending.Any();
    }

    /// <summary>
    /// Creates a backup copy of the SQLite database file before applying migrations.
    /// </summary>
    /// <returns>The backup file path, or null if no backup was created.</returns>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.BackupDatabase
    private static string BackupDatabase(string databasePath)
    {
        try
        {
            if (!File.Exists(databasePath))
            {
                return null;
            }

            var backupPath = databasePath + ".migration-backup";
            File.Copy(databasePath, backupPath, overwrite: true);
            return backupPath;
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Failed to back up database before migration");
            return null;
        }
    }

    /// <summary>
    /// Removes the backup file after a successful migration.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.CleanupBackup
    private static void CleanupBackup(string backupPath)
    {
        try
        {
            if (!string.IsNullOrEmpty(backupPath) && File.Exists(backupPath))
            {
                File.Delete(backupPath);
            }
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Failed to delete migration backup file");
        }
    }

    /// <summary>
    /// Flushes the WAL journal into the main database file using PRAGMA wal_checkpoint.
    /// This is safer than deleting WAL/SHM files directly, which could cause data loss
    /// if uncommitted transactions exist.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.CheckpointWal
    private static void CheckpointWal(string databasePath)
    {
        try
        {
            var connectionString = $"Data source={databasePath}";
            using var connection = new SqliteConnection(connectionString);
            connection.Open();

            using var command = connection.CreateCommand();
            command.CommandText = "PRAGMA wal_checkpoint(TRUNCATE);";
            command.ExecuteNonQuery();

            connection.Close();
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Failed to checkpoint WAL — migration will proceed anyway");
        }
    }

    /// <summary>
    /// Restores the database from backup after a failed migration.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.RestoreBackup
    private static void RestoreBackup(string backupPath, string databasePath)
    {
        try
        {
            if (!string.IsNullOrEmpty(backupPath) && File.Exists(backupPath))
            {
                SqliteConnection.ClearAllPools();
                File.Copy(backupPath, databasePath, overwrite: true);
                AppLogger.Instance.Error(null, "Database restored from backup after migration failure");
            }
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Failed to restore database from backup — manual recovery may be needed");
        }
    }

    /// <summary>
    /// For databases created by <c>EnsureCreated()</c>, the <c>__EFMigrationsHistory</c>
    /// table does not exist. This method creates it and seeds the initial migration entry
    /// so that <c>Migrate()</c> only applies subsequent migrations.
    /// Uses a raw <see cref="SqliteConnection"/> to avoid EF connection pooling locks.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.SeedMigrationHistoryIfNeeded
    private static void SeedMigrationHistoryIfNeeded(string databasePath)
    {
        if (!File.Exists(databasePath))
        {
            return;
        }

        var connectionString = $"Data source={databasePath}";
        using var connection = new SqliteConnection(connectionString);
        connection.Open();

        if (HasMigrationHistoryTable(connection))
        {
            connection.Close();
            return;
        }

        if (!HasExistingTables(connection))
        {
            connection.Close();
            return;
        }

        using var command = connection.CreateCommand();
        command.CommandText =
            "CREATE TABLE IF NOT EXISTS \"__EFMigrationsHistory\" " +
            "(\"MigrationId\" TEXT NOT NULL PRIMARY KEY, \"ProductVersion\" TEXT NOT NULL); " +
            "INSERT OR IGNORE INTO \"__EFMigrationsHistory\" " +
            $"VALUES ('{INITIAL_MIGRATION_ID}', '{EF_PRODUCT_VERSION}');";
        command.ExecuteNonQuery();

        connection.Close();
    }

    /// <summary>
    /// Checks whether the <c>__EFMigrationsHistory</c> table exists in the database.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.HasMigrationHistoryTable
    private static bool HasMigrationHistoryTable(SqliteConnection connection)
    {
        using var command = connection.CreateCommand();
        command.CommandText =
            "SELECT COUNT(*) FROM sqlite_master " +
            "WHERE type='table' AND name='__EFMigrationsHistory'";
        var result = command.ExecuteScalar();
        return result is long count && count > 0;
    }

    /// <summary>
    /// Checks whether the database has existing application tables (created by <c>EnsureCreated()</c>).
    /// </summary>
    // @port: Daqifi.Desktop.Logger.DatabaseMigrator.HasExistingTables
    private static bool HasExistingTables(SqliteConnection connection)
    {
        using var command = connection.CreateCommand();
        command.CommandText =
            "SELECT COUNT(*) FROM sqlite_master " +
            "WHERE type='table' AND name='Samples'";
        var result = command.ExecuteScalar();
        return result is long count && count > 0;
    }
    #endregion
}

/// <summary>
/// Thrown when <see cref="DatabaseMigrator.ReplaceWithEmptyDatabase"/> did not replace the database.
/// </summary>
/// <remarks>
/// The <see cref="Exception.Message"/> is deliberately written for a user, not a developer: the
/// caller shows it verbatim, because "Delete All Sessions" quietly failing while the pane went on
/// listing the sessions is half of what #183 reported. What the user needs to know is whether their
/// data is still there, and it always is — either back at the database path, or, in the one case
/// where it could not be put back, under <see cref="RelocatedDatabasePath"/>.
/// </remarks>
/// <param name="message">The sentence to show the user.</param>
/// <param name="relocatedDatabasePath">
/// Where the original database now sits, when it could NOT be put back; <c>null</c> whenever it was
/// restored (the ordinary failure), so the caller can say nothing moved.
/// </param>
/// <param name="innerException">The failure that stopped the replacement, for the log.</param>
public sealed class DatabaseReplacementException(string message, string? relocatedDatabasePath, Exception? innerException)
    : IOException(message, innerException)
{
    /// <summary>
    /// Where the user's original database was left when it could not be put back, or <c>null</c>
    /// when it is exactly where it always was.
    /// </summary>
    public string? RelocatedDatabasePath { get; } = relocatedDatabasePath;
}
